// Corporate Design auswerten: Schrift, Farben, Logo und Bildmarke aus der Datenbank (Einstellungen > Unternehmen).
// Gilt fuer das angefragte Unternehmen, sonst fuer das eigene. Ist ein CD hinterlegt, aber unvollstaendig oder ungueltig,
// bricht der Workflow mit klarer Meldung ab (kein stiller Ersatz).
// Ist gar kein CD hinterlegt (cd_daten() liefert nichts), kommt ein neutrales Standard-CD mit cd_fehlt: true zurueck,
// damit z. B. die Oberflaeche trotzdem laedt. Aufrufer, die ein echtes CD brauchen, pruefen cd_fehlt.
const eingang = $input.first().json;
const cdRoh = eingang.cd;
const cdFehlt = !cdRoh || typeof cdRoh !== 'object';
const cd = cdFehlt ? {
  unternehmen_id: null,
  unternehmen: null,
  schrift: 'Inter',
  farben: {
    farbe_dunkel: '#1F2933',
    farbe_text_auf_dunkel: '#FFFFFF',
    farbe_akzent: '#52606D',
    farbe_akzent_dunkel: '#323F4B',
    farbe_hell: '#F5F7FA',
    farbe_grau: '#9AA5B1',
    farbe_warnung: '#B54708'
  },
  dateien: {},
  gestaltung: {},
  icons: eingang.icons_ersatz && typeof eingang.icons_ersatz === 'object' ? eingang.icons_ersatz : {}
} : cdRoh;
const wer = cd.unternehmen ? ' (' + cd.unternehmen + ')' : '';
const werte = cd.farben || {};

const farbNamen = ['farbe_dunkel', 'farbe_text_auf_dunkel', 'farbe_akzent', 'farbe_akzent_dunkel', 'farbe_hell', 'farbe_grau', 'farbe_warnung'];
const fehler = [];
if (!cd.schrift) fehler.push('schrift fehlt');
for (const n of farbNamen) {
  if (!werte[n]) fehler.push(n + ' fehlt');
  else if (!/^#[0-9a-fA-F]{6}$/.test(werte[n])) fehler.push(n + ' ist kein Farbwert im Format #RRGGBB (' + werte[n] + ')');
}

const dateien = cd.dateien || {};
const logos = {};
for (const name of ['logo_fuer_dunkel', 'logo_fuer_hell', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell']) {
  const d = dateien[name];
  if (typeof d === 'string' && /^data:image\/(svg\+xml|png);base64,[A-Za-z0-9+/]+={0,2}$/.test(d)) logos[name] = d;
}
if (!cdFehlt) for (const pflicht of ['logo_fuer_dunkel', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell']) if (!logos[pflicht]) fehler.push(pflicht + ' (SVG oder PNG) fehlt');
if (fehler.length) throw new Error('Corporate Design unvollständig' + wer + ': ' + fehler.join('; '));
// Ohne CD gibt es keine Logos und Bildmarken: alle Felder vorhanden, aber leer (null) wie bisher bei logo_fuer_hell.
for (const name of ['logo_fuer_dunkel', 'logo_fuer_hell', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell']) if (!logos[name]) logos[name] = null;

// Feine Abstufungen werden aus den Grundfarben gemischt, damit nur die Grundfarben gepflegt werden muessen.
const rgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
const hex = a => '#' + a.map(v => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, '0')).join('').toUpperCase();
const mische = (a, b, t) => { const x = rgb(a), y = rgb(b); return hex(x.map((v, i) => v + (y[i] - v) * t)); };
const f = {
  dunkel: werte.farbe_dunkel.toUpperCase(),
  textAufDunkel: werte.farbe_text_auf_dunkel.toUpperCase(),
  akzent: werte.farbe_akzent.toUpperCase(),
  akzentDunkel: werte.farbe_akzent_dunkel.toUpperCase(),
  hell: werte.farbe_hell.toUpperCase(),
  grau: werte.farbe_grau.toUpperCase(),
  warnung: werte.farbe_warnung.toUpperCase()
};
const abgeleitet = {
  dunkelNebentext: mische(f.textAufDunkel, f.dunkel, 0.25),
  dunkelLinie: mische(f.dunkel, f.textAufDunkel, 0.08),
  dunkelKarte: mische(f.dunkel, f.textAufDunkel, 0.04),
  dunkelKartenrand: mische(f.dunkel, f.textAufDunkel, 0.1),
  hellNebentext: mische(f.dunkel, f.hell, 0.2),
  hellLinie: mische(f.hell, f.dunkel, 0.1),
  hellKartenrand: mische(f.hell, f.dunkel, 0.06),
  akzentNebentext: mische(f.dunkel, f.akzent, 0.15),
  tabellenLinie: mische(f.hell, f.dunkel, 0.06)
};
const schrift = cd.schrift;
const fontCss = "@import url('https://fonts.googleapis.com/css2?family=" + encodeURIComponent(schrift).replace(/%20/g, '+') + ":wght@400;500;600;700;800&display=block');";
// Gestaltung der Marketing-Grafiken (Folienstile, Akzente, Icons); ohne Angabe wie bisher alles an. Icons für alle Unternehmen gleich.
const gestaltung = Object.assign({ stile: ['dunkel', 'hell', 'akzent'], punkte: true, boegen: true, gross_icon: true, icons: true, icons_aus: [] }, cd.gestaltung || {});
const icons = cd.icons && typeof cd.icons === 'object' ? cd.icons : {};
return [{ json: { schrift, fontCss, farben: f, abgeleitet, logos, gestaltung, icons, unternehmen_id: cdFehlt ? null : cd.unternehmen_id, unternehmen: cd.unternehmen || null, cd_fehlt: cdFehlt } }];
